const body = $input.item.json.body || $input.item.json || {};
const action = body.action || 'analyze_whatsapp_chat';

if (action === 'ping' || action === 'ping_whatsapp_analyzer') {
  return [{
    json: {
      action: 'ping',
      isPing: true,
      ok: true,
      providers: [
        'Groq Whisper (whisper-large-v3-turbo)',
        'Groq LPU (openai/gpt-oss-120b)',
        'Groq LPU (openai/gpt-oss-20b)',
        'Local Ollama fallback (qwen2.5:7b)'
      ]
    }
  }];
}

if (action === 'transcribe_whatsapp_audio') {
  const chatTitle = String(body.chatTitle || 'WhatsApp Conversation').trim();
  const audioFiles = Array.isArray(body.audioFiles) ? body.audioFiles.slice(0, 5) : [];

  if (audioFiles.length === 0) {
    return [{
      json: {
        action: 'ping',
        isPing: true,
        isEmptyAudioBatch: true,
        ok: true,
        providers: ['Groq Whisper (whisper-large-v3-turbo)']
      }
    }];
  }

  const outItems = [];
  for (let idx = 0; idx < audioFiles.length; idx++) {
    const af = audioFiles[idx] || {};
    const rawB64 = String(af.base64Data || '').trim();
    // Clean any data URL prefix if present
    const cleanB64 = rawB64.includes(',') ? rawB64.split(',').pop() : rawB64;

    let binaryData = null;
    if (cleanB64 && cleanB64.length > 64) {
      try {
        const buf = Buffer.from(cleanB64, 'base64');
        if (buf.length > 32) {
          const origName = String(af.fileName || ('voice-note-' + (idx + 1) + '.ogg'));
          // Groq Whisper supports: flac, mp3, mp4, mpeg, mpga, m4a, ogg, wav, webm.
          // WhatsApp .opus files are Ogg Opus containers, so rename .opus -> .ogg for Whisper API compatibility.
          const whisperName = origName
            .replace(/\.opus$/i, '.ogg')
            .replace(/\.aac$/i, '.m4a')
            .replace(/\.3gp$/i, '.mp4');
          const ext = (whisperName.split('.').pop() || 'ogg').toLowerCase();
          const mimeMap = {
            ogg: 'audio/ogg',
            mp3: 'audio/mpeg',
            m4a: 'audio/mp4',
            mp4: 'audio/mp4',
            wav: 'audio/wav',
            webm: 'audio/webm',
            flac: 'audio/flac'
          };
          const whisperMime = mimeMap[ext] || 'audio/ogg';
          binaryData = await this.helpers.prepareBinaryData(buf, whisperName, whisperMime);
        }
      } catch (e) {
        binaryData = null;
      }
    }

    const itemObj = {
      json: {
        action: binaryData ? 'transcribe_whatsapp_audio_whisper' : 'transcribe_whatsapp_audio_context',
        isPing: false,
        isAudioTranscription: true,
        hasBinary: Boolean(binaryData),
        chatTitle,
        index: idx,
        fileName: af.fileName || ('voice-note-' + (idx + 1) + '.opus'),
        messageId: af.messageId || ('msg-' + (idx + 1)),
        sender: af.sender || 'Participant',
        isoDate: af.isoDate || '',
        durationSeconds: Number(af.durationSeconds) || 8,
        mimeType: af.mimeType || 'audio/ogg',
        contextBefore: af.contextBefore || '',
        contextAfter: af.contextAfter || ''
      }
    };

    if (binaryData) {
      itemObj.binary = {
        audioFile: binaryData
      };
    }

    outItems.push(itemObj);
  }

  return outItems;
}

const chatTitle = String(body.chatTitle || 'WhatsApp Conversation').trim();
const metrics = body.quantitativeMetrics || {};
const windows = Array.isArray(body.sampledWindows) ? body.sampledWindows : [];
const wellbeingSignals = Array.isArray(body.wellbeingSignals) ? body.wellbeingSignals.slice(0, 10) : [];
const participants = (Array.isArray(metrics.participants) ? metrics.participants : [])
  .map((p) => String((p && p.name) || '').trim())
  .filter(Boolean)
  .slice(0, 12);

let excerptsText = '';
let excerptCount = 0;
windows.forEach((win, idx) => {
  excerptsText += '\n--- WINDOW ' + (idx + 1) + ': ' + (win.label || win.phase || 'Sample') + ' (' + (win.startDate || '') + ') ---\n';
  const msgs = Array.isArray(win.messages) ? win.messages : [];
  msgs.forEach((m) => {
    excerptCount++;
    excerptsText += '[' + (m.timestamp || '') + '] ' + (m.sender || 'User') + ': ' + String(m.text || '').slice(0, 600) + '\n';
  });
});

const names = participants.length ? participants.join(', ') : 'the participants';

const systemPrompt =
  'You are ChatPulse AI, an evidence-based relationship communication analyst. You read WhatsApp telemetry and sampled excerpts and explain, warmly and concretely, how these people communicate.\n\n' +
  'GROUNDING RULES\n' +
  '- Use the exact participant names: ' + names + '.\n' +
  '- Back every claim with evidence: a metric with its number (e.g. "Lea answers in a median 1 min") or a short quote (max 12 words; if not English, add an English translation in brackets).\n' +
  '- No generic advice. Each recommendation says who, what, and when (use the peak hours/days from the telemetry).\n' +
  '- Write in clear, kind English. Keep the original language only inside quotes.\n' +
  '- If the data is thin, say so and stay modest instead of inventing patterns.\n\n' +
  'SCORING RUBRIC (integers 0-100)\n' +
  '- reciprocityScore: balance of message share, initiation and questions. Near 50/50 with questions both ways = 85+; one side carrying over 70% = below 50.\n' +
  '- emotionalSafetyScore: warmth, gratitude, apologies and repair after tension; contempt, stonewalling or long unanswered gaps lower it.\n' +
  '- engagementVelocityScore: reply speed, streaks, and recent momentum compared with earlier.\n\n' +
  'BOUNDARIES (mandatory)\n' +
  '- Never speculate about, infer or hint at anyone\'s health, medical or mental-health diagnosis, menstrual cycle or period, pregnancy, fertility, sexuality or other sensitive personal traits. If the excerpts mention such things, do not analyse or repeat them.\n' +
  '- Describe moods only as tone visible in the text, never as a cause.\n' +
  '- Labels such as attachmentStyle describe communication habits, not clinical diagnoses.\n' +
  '- Do not encourage monitoring, checking up on or controlling a partner. Favour asking openly and listening.\n' +
  '- If wellbeingSignals are present, suggest a gentle, open check-in for that person; never a diagnosis.\n\n' +
  'OUTPUT: STRICT VALID JSON ONLY (no markdown), with exactly these keys:\n' +
  '{\n' +
  '  "executiveSummary": "3-4 sentences synthesising the dynamic, rhythm and emotional tone, citing at least two numbers",\n' +
  '  "relationshipDynamicTitle": "Short evocative title (2-6 words)",\n' +
  '  "reciprocityScore": 0,\n' +
  '  "emotionalSafetyScore": 0,\n' +
  '  "engagementVelocityScore": 0,\n' +
  '  "mutualInterestBreakdown": {\n' +
  '    "balanceLabel": "Short label citing the message-share percentages",\n' +
  '    "initiationAnalysis": "Who restarts conversations after gaps, with percentages, and what it suggests",\n' +
  '    "responseLatencyAnalysis": "Median reply speeds per person and any double-texting, with numbers",\n' +
  '    "investmentDepthAnalysis": "Words per message, questions asked, voice notes and topical depth, with numbers"\n' +
  '  },\n' +
  '  "participantProfiles": [\n' +
  '    { "name": "Exact name", "attachmentStyle": "Communication-style label", "communicationArchetype": "e.g. The Grounded Anchor", "dominantTraits": ["3-4 traits, each citing a metric or quote"], "emotionalCadence": "1-2 sentences on tone, emoji use and pacing" }\n' +
  '  ],\n' +
  '  "flags": [\n' +
  '    { "type": "green|amber|red", "title": "Specific observation", "evidence": "Concrete metric or quote", "impact": "How it affects trust and closeness" }\n' +
  '  ],\n' +
  '  "conflictAndRepairStyle": "2-3 sentences on how tension, delays or misunderstandings are handled and repaired",\n' +
  '  "recommendations": ["exactly 3 specific, actionable recommendations naming who and when"],\n' +
  '  "relationshipTips": ["3-5 short, kind, practical ways they can support each other"]\n' +
  '}\n' +
  'Include one participantProfiles entry per participant (' + names + '). Give 3-5 flags; use "red" only with clear evidence.';

const userPrompt =
  'CHAT TITLE: ' + chatTitle + '\n' +
  'PARTICIPANTS: ' + names + '\n' +
  'EXCERPTS PROVIDED: ' + excerptCount + '\n\n' +
  'QUANTITATIVE TELEMETRY:\n' + JSON.stringify(metrics, null, 2) + '\n\n' +
  'WELLBEING SIGNALS (dates and text-pattern reasons only):\n' + JSON.stringify(wellbeingSignals, null, 2) + '\n\n' +
  'STRATIFIED CONVERSATION EXCERPTS:\n' + (excerptsText || 'No text excerpts provided.');

return [{
  json: {
    action: 'analyze_whatsapp_chat',
    isPing: false,
    isAudioTranscription: false,
    chatTitle,
    participants,
    aiRouting: body.aiRouting === 'local-first' ? 'local-first' : 'cloud-first',
    systemPrompt,
    userPrompt
  }
}];

// Builds the AI loop state: the provider chain, the prompts and what a valid
// answer must contain. The loop (Prepare -> provider -> Validate) carries it.
const OLLAMA_URL = 'http://host.docker.internal:11434';
// Local fallback, best first: only the first installed one is used, because
// Ollama runs one request at a time and each local answer takes minutes.
const OLLAMA_MODELS = ['qwen2.5:7b', 'llama3.1:8b', 'qwen2.5-coder:7b', 'qwen2.5-coder:3b'];
const MAX_ATTEMPTS = 6;
// The app waits 6 min for an analysis and 4 min for a voice-note batch; the
// loop must answer before that, or its work is lost.
const BUDGET_MS = { chat: 5 * 60_000, audio: 3 * 60_000 };
const GROQ_PRIMARY = { kind: 'groq', model: 'openai/gpt-oss-120b', label: 'Groq LPU (openai/gpt-oss-120b)' };
const GROQ_FAST = { kind: 'groq', model: 'openai/gpt-oss-20b', label: 'Groq LPU (openai/gpt-oss-20b)' };

const origItems = $('Format WhatsApp AI Prompt').all();
const currentInputs = $input.all();
const first = origItems[0]?.json || {};
const isAudio = Boolean(first.isAudioTranscription);

async function installedOllamaModels() {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: OLLAMA_URL + '/api/tags',
      json: true,
      timeout: 3000,
    });
    return (res.models || []).map((m) => m.name);
  } catch (e) {
    return [];
  }
}

const installed = await installedOllamaModels.call(this);
const ollamaChain = OLLAMA_MODELS.filter((m) => installed.includes(m))
  .slice(0, 1)
  .map((model) => ({ kind: 'ollama', model, label: 'Local Ollama (' + model + ')' }));

let state;

if (!isAudio) {
  const cloud = [GROQ_PRIMARY, GROQ_FAST];
  state = {
    action: 'analyze_whatsapp_chat',
    isPing: false,
    isAudioTranscription: false,
    chatTitle: first.chatTitle,
    systemPrompt: first.systemPrompt,
    userPrompt: first.userPrompt,
    temperature: 0.25,
    expected: { participants: first.participants || [] },
    chain: first.aiRouting === 'local-first' ? [...ollamaChain, ...cloud] : [...cloud, ...ollamaChain],
  };
} else {
  const chatTitle = first.chatTitle || 'WhatsApp Conversation';
  const whisperFallbackTranscripts = {};
  const whisperDetails = {};

  const descriptors = origItems.map((item, idx) => {
    const meta = item.json || {};
    const inputJson = currentInputs[idx]?.json || {};
    const whisperText = typeof inputJson.text === 'string' ? inputJson.text.trim() : '';
    const whisperLang = typeof inputJson.language === 'string' ? inputJson.language : '';
    if (whisperText) {
      whisperFallbackTranscripts[meta.fileName] = whisperText;
      whisperDetails[meta.fileName] = {
        transcript: whisperText,
        translation: '',
        language: whisperLang || 'Auto',
        source: 'whisper-large-v3-turbo',
      };
    }
    return {
      fileName: meta.fileName,
      messageId: meta.messageId,
      sender: meta.sender,
      isoDate: meta.isoDate,
      durationSeconds: meta.durationSeconds,
      whisperRawTranscript: whisperText || null,
      whisperDetectedLanguage: whisperLang || null,
      contextBefore: meta.contextBefore || '',
      contextAfter: meta.contextAfter || '',
    };
  });

  const hasAnyWhisper = Object.keys(whisperFallbackTranscripts).length > 0;

  const systemPrompt =
    'You are ChatPulse Multilingual Audio & Translation Intelligence.\n' +
    'For each WhatsApp voice note in the batch:\n' +
    '1. If "whisperRawTranscript" is present, keep its genuine spoken meaning and only fix obvious speech-to-text glitches using the surrounding chat context. Do not add content that was not said.\n' +
    '2. If "whisperRawTranscript" is null (text-only export without audio), write the most plausible short transcript from the speaker, duration (~2.4 words/sec) and contextBefore/contextAfter.\n' +
    '3. "translation": an accurate English translation when the note is in Arabic, Tunisian Derja, French, Spanish or any other language; if already English, repeat the clean English text.\n' +
    '4. "language" (e.g. "Arabic / Derja", "French", "English", "Mixed FR/AR") and emotional "tone" (e.g. "Warm", "Playful", "Direct", "Reassuring", "Tired", "Tense").\n\n' +
    'Use every fileName exactly as given as a key. Respond with STRICT VALID JSON ONLY:\n' +
    '{ "items": { "<exact fileName>": { "transcript": "...", "translation": "...", "language": "...", "tone": "..." } } }';

  const userPrompt =
    'CHAT TITLE: ' + chatTitle + '\n\n' +
    'VOICE NOTE BATCH (' + descriptors.length + ' files):\n' + JSON.stringify(descriptors, null, 2);

  state = {
    action: 'transcribe_whatsapp_audio',
    isPing: false,
    isAudioTranscription: true,
    hasAnyWhisper,
    whisperFallbackTranscripts,
    whisperDetails,
    chatTitle,
    systemPrompt,
    userPrompt,
    temperature: 0.15,
    expected: { files: descriptors.map((d) => d.fileName) },
    // No local fallback for voice notes: a batch on Ollama takes minutes and
    // blocks every other request, so Groq retries a rate limit instead.
    chain: first.aiRouting === 'local-first'
      ? [...ollamaChain, GROQ_FAST, GROQ_PRIMARY]
      : [GROQ_FAST, GROQ_PRIMARY],
  };
}

return [{
  json: {
    ...state,
    ollamaUrl: OLLAMA_URL,
    providerIndex: 0,
    attempt: 0,
    maxAttempts: MAX_ATTEMPTS,
    repair: null,
    repairedProviders: [],
    log: [],
    best: null,
    accept: false,
    rateRetried: [],
    waitMs: 0,
    deadlineAt: Date.now() + (isAudio ? BUDGET_MS.audio : BUDGET_MS.chat),
  },
}];

const firstPromptItem = $('Format WhatsApp AI Prompt').first()?.json || {};

if (firstPromptItem.isPing) {
  if (firstPromptItem.isEmptyAudioBatch) {
    return [{
      json: {
        ok: true,
        success: true,
        action: 'transcribe_whatsapp_audio',
        provider: 'Groq Whisper (whisper-large-v3-turbo)',
        transcripts: {},
        translations: {},
        details: {}
      }
    }];
  }
  return [{
    json: {
      ok: true,
      success: true,
      action: 'ping',
      latencyMs: 18,
      providers: firstPromptItem.providers
    }
  }];
}

// The AI loop's final state (Validate & Score AI Output).
const s = $input.first().json || {};
const attempts = Array.isArray(s.log) ? s.log : [];
const parsed = s.finalResult && typeof s.finalResult === 'object' ? s.finalResult : null;
const qualityWarnings = Array.isArray(s.finalErrors) ? s.finalErrors : [];
const providerUsed = s.finalProvider || 'n8n AI';

if (s.isAudioTranscription) {
  const transcripts = { ...(s.whisperFallbackTranscripts || {}) };
  const translations = {};
  const details = { ...(s.whisperDetails || {}) };
  const source = s.hasAnyWhisper ? 'whisper+llm' : 'context-llm';
  const itemsMap = parsed ? (parsed.items || parsed.transcripts || parsed) : null;

  if (itemsMap && typeof itemsMap === 'object') {
    for (const [key, val] of Object.entries(itemsMap)) {
      if (typeof val === 'string' && val.trim()) {
        transcripts[key] = val.trim();
        details[key] = {
          transcript: val.trim(),
          translation: '',
          language: details[key]?.language || 'Auto',
          tone: 'Conversational',
          source
        };
      } else if (val && typeof val === 'object') {
        const tText = String(val.transcript || val.text || transcripts[key] || '').trim();
        const trText = String(val.translation || '').trim();
        if (tText) transcripts[key] = tText;
        if (trText) translations[key] = trText;
        details[key] = {
          transcript: tText || transcripts[key] || '',
          translation: trText,
          language: String(val.language || details[key]?.language || 'Auto').trim(),
          tone: String(val.tone || 'Conversational').trim(),
          source
        };
      }
    }
  }

  return [{
    json: {
      ok: true,
      success: true,
      action: 'transcribe_whatsapp_audio',
      provider: s.hasAnyWhisper ? 'Groq Whisper v3 Turbo + ' + providerUsed : providerUsed + ' · Contextual Audio Intelligence',
      analyzedAt: new Date().toISOString(),
      transcripts,
      translations,
      details,
      attempts,
      qualityWarnings,
      backoffMs: s.backoffMs || 0
    }
  }];
}

if (!parsed) {
  const lastError = attempts.length ? attempts[attempts.length - 1].outcome : 'no AI provider answered';
  return [{
    json: {
      success: false,
      ok: false,
      error: 'All AI providers failed (' + attempts.length + ' attempts). Last: ' + lastError,
      provider: providerUsed,
      attempts,
      backoffMs: s.backoffMs || 0,
      analyzedAt: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    ...parsed,
    success: true,
    ok: true,
    provider: providerUsed,
    analyzedAt: new Date().toISOString(),
    attempts,
    qualityWarnings,
    backoffMs: s.backoffMs || 0
  }
}];

// One loop iteration: the request for the current provider. A repair attempt
// replays the previous answer and lists what was wrong with it.
const s = $input.first().json;
const p = s.chain[s.providerIndex];

// A rate-limited provider is retried after the wait it asked for.
if (s.waitMs > 0 && typeof setTimeout === 'function') {
  await new Promise((resolve) => setTimeout(resolve, s.waitMs));
}

// Never let one call run past the loop's deadline.
const remaining = Math.max(10_000, (s.deadlineAt || Date.now() + 60_000) - Date.now() - 5_000);
// A local model may use whatever is left of the deadline.
const timeoutMs = p.kind === 'ollama' ? remaining : Math.min(60_000, remaining);

const messages = [
  { role: 'system', content: s.systemPrompt },
  { role: 'user', content: s.userPrompt },
];
if (s.repair) {
  messages.push({ role: 'assistant', content: s.repair.previous });
  messages.push({ role: 'user', content: s.repair.instruction });
}

const requestBody = p.kind === 'ollama'
  ? {
      model: p.model,
      messages,
      stream: false,
      format: 'json',
      keep_alive: '10m',
      options: { temperature: s.temperature, num_ctx: 8192, num_predict: s.isAudioTranscription ? 900 : 1800 },
    }
  : {
      model: p.model,
      messages,
      temperature: s.temperature,
      // Groq counts the reserved completion budget against tokens-per-minute,
      // so keep it close to what an answer needs.
      max_completion_tokens: s.isAudioTranscription ? 1500 : 3000,
      ...(String(p.model).startsWith('openai/gpt-oss') ? { reasoning_effort: 'low' } : {}),
      response_format: { type: 'json_object' },
    };

return [{
  json: {
    ...s,
    provider: p,
    requestBody,
    requestUrl: p.kind === 'ollama'
      ? s.ollamaUrl + '/api/chat'
      : 'https://api.groq.com/openai/v1/chat/completions',
    timeoutMs,
    waitMs: 0,
    attemptStartedAt: Date.now(),
  },
}];

// Checks one AI answer and decides the next step of the loop:
// accept it, ask the same model to repair it once, or fall back to the next
// provider. After MAX attempts the best answer seen so far is used.
let s;
try {
  s = $('Prepare AI Attempt').first(0, $runIndex).json;
} catch (e) {
  s = $('Prepare AI Attempt').last().json;
}
const p = s.provider;
const res = $input.first().json || {};
const ms = Date.now() - (s.attemptStartedAt || Date.now());

const content = p.kind === 'ollama'
  ? String(res.message?.content || '')
  : String(res.choices?.[0]?.message?.content || '');

let httpError = null;
if (res.error) {
  // n8n puts a generic message in .message and the provider's own text
  // (e.g. Groq's "... tokens per day (TPD) ... try again in 4m16s") in .description.
  const e = res.error;
  httpError = typeof e === 'string'
    ? e
    : [e.message, e.description, e.cause && e.cause.message]
        .filter((x, i, a) => x && a.indexOf(x) === i)
        .join(' — ') || JSON.stringify(e);
} else if (!content.trim()) {
  httpError = 'empty response';
}

function extractJson(text) {
  let t = text.trim();
  if (t.startsWith('```')) t = t.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a !== -1 && b > a) t = t.slice(a, b + 1);
  return JSON.parse(t);
}

const isStr = (v, min = 1) => typeof v === 'string' && v.trim().length >= min;
const isScore = (v) => Number.isInteger(Number(v)) && Number(v) >= 0 && Number(v) <= 100 && v !== '' && v !== null;
const norm = (v) => String(v || '').trim().toLowerCase();

// Words that mean the model speculated about health or the menstrual cycle.
const SENSITIVE = /\b(menstrua\w*|pms|premenstrual|pregnan\w*|ovulat\w*|hormon\w*|(her|his|their) period|on (her|his|their) period|time of (the )?month|bipolar|clinical(ly)? depress\w*|mental (illness|disorder)|(anxiety|personality|eating) disorder)\b/i;

function validateChat(o, expected) {
  const errors = [];
  for (const k of ['executiveSummary', 'relationshipDynamicTitle', 'conflictAndRepairStyle']) {
    if (!isStr(o[k], 10)) errors.push('"' + k + '" is missing or too short');
  }
  if (isStr(o.executiveSummary) && o.executiveSummary.length < 160) {
    errors.push('"executiveSummary" must be 3-4 full sentences citing numbers');
  }
  for (const k of ['reciprocityScore', 'emotionalSafetyScore', 'engagementVelocityScore']) {
    if (!isScore(o[k])) errors.push('"' + k + '" must be an integer 0-100');
  }
  const m = o.mutualInterestBreakdown;
  if (!m || typeof m !== 'object') {
    errors.push('"mutualInterestBreakdown" object is missing');
  } else {
    for (const k of ['balanceLabel', 'initiationAnalysis', 'responseLatencyAnalysis', 'investmentDepthAnalysis']) {
      if (!isStr(m[k], 8)) errors.push('"mutualInterestBreakdown.' + k + '" is missing');
    }
  }
  const profiles = Array.isArray(o.participantProfiles) ? o.participantProfiles : [];
  const names = (expected.participants || []).map(norm);
  const got = profiles.map((x) => norm(x && x.name));
  const missing = (expected.participants || []).filter((n) => !got.includes(norm(n)));
  if (missing.length) errors.push('participantProfiles is missing: ' + missing.join(', '));
  const unknown = profiles.map((x) => x && x.name).filter((n) => names.length && !names.includes(norm(n)));
  if (unknown.length) errors.push('participantProfiles uses names not in the chat: ' + unknown.join(', ') + ' (use exactly: ' + expected.participants.join(', ') + ')');
  profiles.forEach((x, i) => {
    if (!x || !isStr(x.emotionalCadence, 10) || !Array.isArray(x.dominantTraits) || x.dominantTraits.length < 2) {
      errors.push('participantProfiles[' + i + '] needs emotionalCadence and 3-4 dominantTraits');
    }
  });
  const flags = Array.isArray(o.flags) ? o.flags : [];
  if (flags.length < 2) errors.push('give 3-5 flags');
  flags.forEach((f, i) => {
    if (!f || !['green', 'amber', 'red'].includes(norm(f.type)) || !isStr(f.title) || !isStr(f.evidence, 10) || !isStr(f.impact, 10)) {
      errors.push('flags[' + i + '] needs type green|amber|red, title, evidence and impact');
    }
  });
  const recs = Array.isArray(o.recommendations) ? o.recommendations.filter((r) => isStr(r, 15)) : [];
  if (recs.length < 3) errors.push('give exactly 3 specific recommendations');
  if (names.length && recs.length && !recs.some((r) => names.some((n) => norm(r).includes(n)))) {
    errors.push('recommendations must name who should act (' + expected.participants.join(', ') + ')');
  }
  const tips = Array.isArray(o.relationshipTips) ? o.relationshipTips.filter((r) => isStr(r, 10)) : [];
  if (tips.length < 3) errors.push('give 3-5 relationshipTips');
  const hit = JSON.stringify(o).match(SENSITIVE);
  if (hit) errors.push('remove all health/medical/menstrual speculation (found "' + hit[0] + '")');
  return errors;
}

function validateAudio(o, expected) {
  const errors = [];
  const items = (o && (o.items || o.transcripts)) || o;
  if (!items || typeof items !== 'object') return ['"items" object is missing'];
  for (const f of expected.files || []) {
    const v = items[f];
    const text = typeof v === 'string' ? v : v && (v.transcript || v.text);
    if (!isStr(text)) errors.push('missing transcript for "' + f + '"');
    else if (typeof v === 'object' && !isStr(v.translation)) errors.push('missing translation for "' + f + '"');
  }
  return errors;
}

let parsed = null;
let errors = [];
if (!httpError) {
  try {
    parsed = extractJson(content);
    errors = s.isAudioTranscription ? validateAudio(parsed, s.expected) : validateChat(parsed, s.expected);
  } catch (e) {
    errors = ['the answer was not valid JSON'];
  }
}

const outcome = httpError
  ? 'error: ' + String(httpError).slice(0, 160)
  : errors.length ? 'needs repair: ' + errors.slice(0, 4).join('; ') : 'accepted';
const log = [...(s.log || []), {
  attempt: s.attempt + 1,
  provider: p.label,
  repair: Boolean(s.repair),
  ms,
  outcome,
}];

let best = s.best;
if (parsed && (!best || errors.length < best.errors.length)) {
  best = { result: parsed, provider: p.label, errors };
}

const base = { ...s };
delete base.requestBody;
delete base.provider;

if (parsed && errors.length === 0) {
  return [{ json: { ...base, log, best, accept: true, finalResult: parsed, finalProvider: p.label, finalErrors: [] } }];
}

const next = { ...base, log, best, attempt: s.attempt + 1 };
const rateLimited = Boolean(httpError) && /rate limit|too many requests|\b429\b/i.test(httpError);
// A slow local repair that can't finish before the deadline is skipped.
const timeLeft = (s.deadlineAt || Infinity) - Date.now();
const repairFits = p.kind !== 'ollama' || timeLeft > ms + 10_000;
const canRepair = !httpError && repairFits && !(s.repairedProviders || []).includes(s.providerIndex);
// Groq says how long to wait: "Please try again in 7.5s" or "in 4m16.6s".
let askedMs = 5000;
if (rateLimited) {
  const m = /try again in (?:(\d+)m)?\s*([\d.]+)\s*(ms|s)/i.exec(httpError);
  if (m) askedMs = Number(m[1] || 0) * 60_000 + Number(m[2]) * (m[3] === 'ms' ? 1 : 1000);
  // Tell the app how long to space out its next request (per-minute limits only).
  if (!/per day|\(TPD\)|\(RPD\)/i.test(httpError)) {
    next.backoffMs = Math.max(s.backoffMs || 0, Math.min(60_000, Math.ceil(askedMs)));
  }
}
// A daily limit or a long wait won't clear in time: move on at once.
const worthWaiting = rateLimited && askedMs <= 20_000 && !/per day|\(TPD\)|\(RPD\)/i.test(httpError);
if (worthWaiting && !(s.rateRetried || []).includes(s.providerIndex)) {
  next.waitMs = Math.max(1500, Math.ceil(askedMs) + 500);
  next.rateRetried = [...(s.rateRetried || []), s.providerIndex];
  next.repair = null;
} else if (canRepair) {
  next.repair = {
    previous: content.slice(0, 8000),
    instruction:
      'Your JSON answer has these problems:\n- ' + errors.join('\n- ') +
      '\nReturn the complete corrected JSON object only, with every required key, and nothing else.',
  };
  next.repairedProviders = [...(s.repairedProviders || []), s.providerIndex];
} else {
  next.repair = null;
  next.providerIndex = s.providerIndex + 1;
}

const outOfTime = Date.now() + (next.waitMs || 0) > (s.deadlineAt || Infinity) - 20_000;
if (next.attempt >= s.maxAttempts || next.providerIndex >= s.chain.length || outOfTime) {
  return [{ json: {
    ...next,
    accept: true,
    exhausted: true,
    finalResult: best ? best.result : null,
    finalProvider: best ? best.provider : p.label,
    finalErrors: best ? best.errors : [httpError || 'no valid answer'],
    outOfTime,
  } }];
}

return [{ json: { ...next, accept: false } }];
